const BY_KEY = new Map(BRANDS.map((b) => [b.key, b]));
export const brandByKey = (key: string): Brand | undefined => BY_KEY.get(key);

/** Brands offered in the "Social icons" list, in display order. */
export const SOCIAL_BRANDS = BRANDS.filter((b) => b.social);

const HOST_INDEX: [string, Brand][] = BRANDS.flatMap((b) => b.hosts.map((h) => [h, b] as [string, Brand]));

/** The brand a web address belongs to (instagram.com/x, www.youtube.com, m.facebook.com...), or undefined. Only the host is read. */
export function brandForUrl(url: string | null | undefined): Brand | undefined {
  if (!url) return undefined;
  let host: string;
  try { host = new URL(/^[a-z][a-z0-9+.-]*:/i.test(url) ? url : `https://${url}`).hostname.toLowerCase(); } catch { return undefined; }
  host = host.replace(/\.$/, "");
  for (const [h, b] of HOST_INDEX) if (host === h || host.endsWith(`.${h}`)) return b;
  return undefined;
}
